package com.cartalaap.garage;import java.time.Instant;import java.util.List;
public record GarageVehicleResponse(Long id,VehicleType vehicleType,GarageStatus status,String brand,String model,Integer year,String variant,String fuelType,String modifications,String ownershipStory,List<String>imageUrls,Instant createdAt,boolean ownedByCurrentUser){static GarageVehicleResponse from(GarageVehicle v,boolean owned){return new GarageVehicleResponse(v.getId(),v.getVehicleType(),v.getStatus(),v.getBrand(),v.getModel(),v.getYear(),v.getVariant(),v.getFuelType(),v.getModifications(),v.getOwnershipStory(),v.getImages().stream().map(GarageVehicleImage::getImageUrl).toList(),v.getCreatedAt(),owned);}}
